import pytest


class DivZero(Exception):
    def __init__(self, a: int) -> None:
        self.a: int = a


def safe_div(a: int, b: int) -> int:
    """Return a divided by b using integer (floor) division.

    Raises DivZero(a) when b is 0.
    """
    if b == 0:
        raise DivZero(a)
    return a // b


def test_safe_div_basic() -> None:
    assert safe_div(7, 2) == 3


def test_safe_div_negative_floors() -> None:
    assert safe_div(-7, 2) == -4


def test_safe_div_exact() -> None:
    assert safe_div(9, 3) == 3


def test_safe_div_zero_numerator() -> None:
    assert safe_div(0, 5) == 0


def test_safe_div_by_zero_carries_numerator() -> None:
    with pytest.raises(DivZero) as info:
        safe_div(7, 0)
    assert info.value.a == 7
